set_budget:
def set_budget(state, category, amount) do
  if not is_binary(category), do: raise("category must be a string")
  if not (is_number(amount) and amount >= 0), do: raise("amount must be a non-negative number")
  budgets = Map.get(state, "budgets", %{}) |> Map.put(category, to_cents(amount))
  {to_cents(amount), Map.put(state, "budgets", budgets)}
end

store_expense:
defp store_expense(state, amount, category, note) do
  if not (is_number(amount) and amount > 0), do: raise("amount must be a positive number")
  if not (is_binary(category) and category != ""), do: raise("category must be a non-empty string")
  expenses = Map.get(state, "expenses", [])
  base = %{"amount" => amount, "category" => category}
  expense = if is_nil(note), do: base, else: Map.put(base, "note", note)
  new_expenses = expenses ++ [expense]
  {length(new_expenses), Map.put(state, "expenses", new_expenses)}
end
